<script>
 import { BookOpen, Settings, Cable, Sparkles, FileText } from 'lucide-svelte';
 let { context }=$props();
 const title=value=>String(value||'').replaceAll('_',' ');
</script>
{#if !context}<p class="muted">Resolving context…</p>{:else if context.message}<p class="help">{context.message}</p>{:else}<div class="context-grid"><section><h3><BookOpen size={16}/>Workspace instructions</h3>{#if context.metadata?.workspace_brief}<p class="help">{context.metadata.workspace_brief.source==='purpose'?'Workspace purpose':`Published brief · revision ${context.metadata.workspace_brief.revision||'current'}`}</p>{:else}<p class="help">Personal context{context.metadata?.project?' · Project goal included':''}</p>{/if}{#if context.metadata?.conversation_summary}<p class="help">Rolling summary through {context.metadata.conversation_summary.completed_turns} completed turns.</p>{/if}</section><section><h3><Settings size={16}/>Preferences applied</h3>{#each Object.entries(context.metadata?.preferences?.applied||{}) as [key,value]}{#if value}<p class="help"><strong>{title(key)}:</strong> {value}</p>{/if}{:else}<p class="help">Installation defaults</p>{/each}</section><section><h3><Sparkles size={16}/>Relevant skills</h3>{#each context.skills||[] as skill}<p class="help"><strong>{skill.name}</strong>{skill.description?` — ${skill.description}`:''}</p>{:else}<p class="help">No specialized skill selected.</p>{/each}</section><section><h3><Cable size={16}/>Available tools</h3><div class="attendee-chips">{#each context.tools||[] as tool}<span class="tag">{title(tool)}</span>{/each}</div></section></div><details><summary>Authorized source references · {context.sources?.length||0}</summary>{#each context.sources||[] as source}<p class="source-ref"><strong>{source.title||source.filename||title(source.type)}</strong>{source.chunk!=null?` · Chunk ${source.chunk}`:''}{source.summary_only?' · Published summary':''}</p>{:else}<p class="help">No relevant saved source matched this preview. The agent may query authorized tools during execution.</p>{/each}</details>{/if}
